CREATE TYPE "ExpenseStatus" AS ENUM ('PENDING', 'APPROVED', 'VOIDED');
CREATE TYPE "ComplaintCategory" AS ENUM ('SERVICE', 'FOOD', 'PAYMENT', 'OTHER');
CREATE TYPE "ComplaintPriority" AS ENUM ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL');
CREATE TYPE "ComplaintStatus" AS ENUM ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED');
CREATE TABLE "ExpenseCategory" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdByUserId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ExpenseCategory_pkey" PRIMARY KEY ("id"), CONSTRAINT "ExpenseCategory_name_key" UNIQUE ("name"), CONSTRAINT "ExpenseCategory_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ExpenseTransaction" ("id" TEXT NOT NULL, "categoryId" TEXT NOT NULL, "vendor" TEXT, "amount" DECIMAL(14,2) NOT NULL, "paymentMethod" TEXT, "paidAt" DATE NOT NULL, "receiptReference" TEXT, "isFixed" BOOLEAN NOT NULL DEFAULT false, "isRecurring" BOOLEAN NOT NULL DEFAULT false, "status" "ExpenseStatus" NOT NULL DEFAULT 'PENDING', "note" TEXT, "createdByUserId" TEXT NOT NULL, "approvedByUserId" TEXT, "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ExpenseTransaction_pkey" PRIMARY KEY ("id"), CONSTRAINT "ExpenseTransaction_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "ExpenseCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "ExpenseTransaction_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "ExpenseTransaction_approvedByUserId_fkey" FOREIGN KEY ("approvedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE); CREATE INDEX "ExpenseTransaction_paidAt_status_idx" ON "ExpenseTransaction"("paidAt", "status");
CREATE TABLE "OwnerWithdrawal" ("id" TEXT NOT NULL, "amount" DECIMAL(14,2) NOT NULL, "withdrawnAt" DATE NOT NULL, "reason" TEXT NOT NULL, "receiptReference" TEXT, "createdByUserId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OwnerWithdrawal_pkey" PRIMARY KEY ("id"), CONSTRAINT "OwnerWithdrawal_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE INDEX "OwnerWithdrawal_withdrawnAt_idx" ON "OwnerWithdrawal"("withdrawnAt");
ALTER TABLE "SupplierPurchaseOrder" ADD COLUMN "emergencyPurchase" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "SupplierReceiving" ("id" TEXT NOT NULL, "purchaseOrderId" TEXT NOT NULL, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "receivedByUserId" TEXT NOT NULL, "qualityRating" INTEGER, "rejectionQuantity" DECIMAL(12,3), "rejectionReason" TEXT, "completionNote" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupplierReceiving_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierReceiving_purchaseOrderId_key" UNIQUE ("purchaseOrderId"), CONSTRAINT "SupplierReceiving_purchaseOrderId_fkey" FOREIGN KEY ("purchaseOrderId") REFERENCES "SupplierPurchaseOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SupplierReceiving_receivedByUserId_fkey" FOREIGN KEY ("receivedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "SupplierReceivingItem" ("id" TEXT NOT NULL, "receivingId" TEXT NOT NULL, "purchaseOrderItemId" TEXT NOT NULL, "expectedQuantity" DECIMAL(12,3) NOT NULL, "receivedQuantity" DECIMAL(12,3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SupplierReceivingItem_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierReceivingItem_receivingId_purchaseOrderItemId_key" UNIQUE ("receivingId", "purchaseOrderItemId"), CONSTRAINT "SupplierReceivingItem_receivingId_fkey" FOREIGN KEY ("receivingId") REFERENCES "SupplierReceiving"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "SupplierReceivingItem_purchaseOrderItemId_fkey" FOREIGN KEY ("purchaseOrderItemId") REFERENCES "SupplierPurchaseOrderItem"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "CustomerFeedback" ("id" TEXT NOT NULL, "orderId" TEXT, "rating" INTEGER, "comment" TEXT, "createdByUserId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CustomerFeedback_pkey" PRIMARY KEY ("id"), CONSTRAINT "CustomerFeedback_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "CustomerFeedback_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "CustomerFeedback_rating_check" CHECK ("rating" IS NULL OR "rating" BETWEEN 1 AND 5));
CREATE TABLE "ComplaintCase" ("id" TEXT NOT NULL, "orderId" TEXT, "category" "ComplaintCategory" NOT NULL, "priority" "ComplaintPriority" NOT NULL DEFAULT 'MEDIUM', "status" "ComplaintStatus" NOT NULL DEFAULT 'OPEN', "description" TEXT NOT NULL, "assignedToUserId" TEXT, "resolvedByUserId" TEXT, "resolutionNotes" TEXT, "resolvedAt" TIMESTAMP(3), "createdByUserId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ComplaintCase_pkey" PRIMARY KEY ("id"), CONSTRAINT "ComplaintCase_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "ComplaintCase_assignedToUserId_fkey" FOREIGN KEY ("assignedToUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "ComplaintCase_resolvedByUserId_fkey" FOREIGN KEY ("resolvedByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT "ComplaintCase_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
